package main
import("context";"encoding/json";"fmt";"os";"time";sharedmongo "github.com/xKoRx/sdk/pkg/shared/mongo";"github.com/xKoRx/symphony/internal/di";metadatamongo "github.com/xKoRx/symphony/sqx/adapters/metadata-mongo";registrypostgres "github.com/xKoRx/symphony/sqx/adapters/registry-postgres";"github.com/xKoRx/symphony/sqx/core/forge")
func main(){ref:=os.Args[1];if err:=di.InitSelective("sqx-worker",di.WithEnvironment(os.Getenv("ENV")),di.WithEtcd(),di.WithPostgres());err!=nil{panic(err)};defer di.Close();ctx,cancel:=context.WithTimeout(context.Background(),30*time.Second);defer cancel();mc,err:=sharedmongo.New(di.Container.Etcd,di.Container.Telemetry);if err!=nil{panic(err)};defer mc.Close(ctx);control:=registrypostgres.NewControlPlaneFromClient(di.Container.Postgres);rank:=metadatamongo.NewRankingSnapshotStore(mc.Raw(),mc.DatabaseName());out,err:=forge.NewService(control,rank,control).Result(ctx,ref,"");if err!=nil{fmt.Fprintln(os.Stderr,err)};b,_:=json.MarshalIndent(out,"","  ");fmt.Println(string(b))}
